CREATE DATABASE IF NOT EXISTS loan_management_system CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE loan_management_system;
CREATE TABLE IF NOT EXISTS auth_accounts(uid CHAR(36) PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,email_verified BOOLEAN NOT NULL DEFAULT TRUE,account_status ENUM('pending_activation','active','locked','disabled') NOT NULL DEFAULT 'active',failed_attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,locked_until DATETIME(3) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS records(collection_name VARCHAR(64) NOT NULL,id VARCHAR(128) NOT NULL,data JSON NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),PRIMARY KEY(collection_name,id),INDEX idx_records_collection_created(collection_name,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id CHAR(36) NULL,actor_id CHAR(36) NULL,event_type VARCHAR(64) NOT NULL,result VARCHAR(32) NOT NULL,details JSON NULL,ip_address VARCHAR(64) NULL,user_agent VARCHAR(512) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX idx_audit_created(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS otp_challenges(id CHAR(36) PRIMARY KEY,email VARCHAR(254) NOT NULL,phone VARCHAR(32) NOT NULL,code_hash CHAR(64) NOT NULL,expires_at DATETIME(3) NOT NULL,attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,consumed_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX idx_otp_destination(email,created_at)) ENGINE=InnoDB;
